func parsePermissionRequest(raw json.RawMessage) (policy.PermissionRequestInput, error) {
	var r policy.PermissionRequestInput
	d := json.NewDecoder(bytes.NewReader(raw))
	d.DisallowUnknownFields()
	if err := d.Decode(&r); err != nil {
		return r, core.Invalid("arguments", "invalid permission request")
	}
	if d.Decode(new(any)) != io.EOF {
		return r, core.Invalid("arguments", "one object required")
	}
	return r, r.Normalize(time.Now())
}
